export interface ConnectorConfig {
  airtablePersonalAccessToken: string
  airtableBaseId: string
  airtableTableIdOrName: string
  fetch?: typeof fetch
}

export interface ShopifyWebhookPayload {
  ucp: {
    version: string
    capabilities: Record<string, Array<{ version: string }>>
  }
  id: string
  label: string
  currency: string
  totals: Array<{
    type: string
    display_text: string
    amount: number
  }>
  line_items: unknown[]
  fulfillment: Record<string, unknown>
  customer?: { email?: string }
  email?: string
}

export interface HandleResult {
  recordId: string
  createdTime: string
  fields: Record<string, unknown>
}

export async function handle(payload: ShopifyWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.id) {
    throw new Error('Missing required field: id (order ID)')
  }
  if (!payload.totals || !Array.isArray(payload.totals)) {
    throw new Error('Missing required field: totals array')
  }

  const totalEntry = payload.totals.find((t) => t.type === 'total')
  if (!totalEntry || typeof totalEntry.amount !== 'number') {
    throw new Error('Missing required field: totals entry with type "total" and numeric amount')
  }

  const orderId = payload.id
  const totalPrice = totalEntry.amount / 100
  const email = payload.customer?.email || payload.email || ''

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableIdOrName}`

  const fields: Record<string, unknown> = {
    'Order ID': orderId,
    'Total': totalPrice,
  }

  if (email) {
    fields['Customer Email'] = email
  }

  const body = JSON.stringify({
    records: [{ fields }],
  })

  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtablePersonalAccessToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at ${url}`)
  }

  const data = (await response.json()) as {
    records: Array<{ id: string; createdTime: string; fields: Record<string, unknown> }>
  }

  if (!data.records || data.records.length === 0) {
    throw new Error('Airtable API returned no records')
  }

  const record = data.records[0]
  return {
    recordId: record.id,
    createdTime: record.createdTime,
    fields: record.fields,
  }
}

