        'Order ID': 'gid://shopify/Order/6252199051413',
        'Customer Email': 'customer@example.com',
        'Total': 79.77,
      })
      return jsonResponse({
        records: [
          {
            id: 'recABC123def456',
            createdTime: '2023-01-01T12:00:00.000Z',
            fields: body.records[0].fields,
          },
        ],
      })
    })

    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'pat_test123',
      airtableBaseId: 'appTestBase',
      airtableTableIdOrName: 'Orders',
      fetch,
