    const result = await handle(payload, config)
    expect(result.recordId).toBe('recABC123def456')
    expect(result.fields['Order ID']).toBe('gid://shopify/Order/6252199051413')
    expect(result.fields['Customer Email']).toBe('customer@example.com')
    expect(result.fields['Total']).toBe(79.77)
  })

