    const payload: ShopifyWebhookPayload = {
      ...SOURCE_EXAMPLE,
      totals: [{ type: 'total', display_text: 'total', amount: 5000 }],
    }

    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { records: Array<{ fields: Record<string, unknown> }> }
      expect(body.records[0].fields).not.toHaveProperty('Customer Email')
      expect(body.records[0].fields['Total']).toBe(50)
      return jsonResponse({
        records: [
          {
            id: 'rec1',
            createdTime: '2023-01-01T12:00:00.000Z',
            fields: body.records[0].fields,
          },
        ],
      })
    })

    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'pat_test123',
      airtableBaseId: 'appTestBase',
      airtableTableIdOrName: 'Orders',
      fetch,
    }

    await handle(payload, config)
  })

  it('throws on missing order id', async () => {
    const payload = { ...SOURCE_EXAMPLE, id: '' }
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'pat_test123',
      airtableBaseId: 'appTestBase',
      airtableTableIdOrName: 'Orders',
      fetch,
    }

    await expect(handle(payload as unknown as ShopifyWebhookPayload, config)).rejects.toThrow(
      'Missing required field: id'
    )
  })

  it('throws on missing totals array', async () => {
    const payload = { ...SOURCE_EXAMPLE, totals: undefined as any }
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'pat_test123',
      airtableBaseId: 'appTestBase',
      airtableTableIdOrName: 'Orders',
      fetch,
    }

    await expect(handle(payload as unknown as ShopifyWebhookPayload, config)).rejects.toThrow(
      'Missing required field: totals array'
    )
  })

  it('throws on missing total type in totals', async () => {
    const payload = { ...SOURCE_EXAMPLE, totals: [{ type: 'subtotal', display_text: 'subtotal', amount: 100 }] }
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'pat_test123',
      airtableBaseId: 'appTestBase',
      airtableTableIdOrName: 'Orders',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Missing required field: totals entry with type "total"'
    )
  })

  it('throws on non-2xx Airtable response', async () => {
    const payload: ShopifyWebhookPayload = {
      ...SOURCE_EXAMPLE,
      totals: [{ type: 'total', display_text: 'total', amount: 7977 }],
    }
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'pat_test123',
      airtableBaseId: 'appTestBase',
      airtableTableIdOrName: 'Orders',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Airtable API error: 401 Unauthorized at https://api.airtable.com/v0/appTestBase/Orders'
    )
    expect(calls[0].url).toBe('https://api.airtable.com/v0/appTestBase/Orders')
  })
